from decimal import Decimal, InvalidOperation
from fractions import Fraction
from functools import cmp_to_key

_CENT = Decimal("0.01")

def _decimal_to_fraction(d: Decimal) -> Fraction:
    # d is finite Decimal
    sign, digits, exp = d.as_tuple()
    if not digits:
        return Fraction(0, 1)
    coeff = 0
    for dig in digits:
        coeff = coeff * 10 + dig
    if sign:
        coeff = -coeff
    if exp >= 0:
        return Fraction(coeff * (10 ** exp), 1)
    else:
        return Fraction(coeff, 10 ** (-exp))

def allocate_by_ratios(total: str, ratios: list) -> list[Decimal]:
    if not isinstance(total, str):
        raise ValueError("total must be a string")
    try:
        amount = Decimal(total)
    except (InvalidOperation, ValueError):
        raise ValueError(f"invalid total: {total!r}") from None
    if not amount.is_finite():
        raise ValueError("total must be finite")
    # Validate at most 2 decimal places and compute cents exactly using tuple arithmetic
    sign_t, digits_t, exp_t = amount.as_tuple()
    # Build coefficient for total
    if not digits_t:
        coeff_t = 0
    else:
        coeff_t = 0
        for dig in digits_t:
            coeff_t = coeff_t * 10 + dig
        if sign_t:
            coeff_t = -coeff_t
    # amount = coeff_t * 10**exp_t
    # amount * 100 = coeff_t * 10**(exp_t+2) must be integral
    shift = exp_t + 2
    if shift >= 0:
        total_cents_exact = coeff_t * (10 ** shift)  # may be negative
    else:
        divisor = 10 ** (-shift)
        if coeff_t % divisor != 0:
            raise ValueError("total must have at most 2 decimal places")
        total_cents_exact = coeff_t // divisor
    # total_cents_exact is total in cents as int (signed)
    if not isinstance(ratios, list) or len(ratios) == 0:
        raise ValueError("ratios must be a non-empty list")
    weights = []
    for entry in ratios:
        if isinstance(entry, bool):
            raise ValueError("bool weights are not accepted")
        if isinstance(entry, int):
            weight = Decimal(entry)
        elif isinstance(entry, Decimal):
            weight = entry
        elif isinstance(entry, str):
            try:
                weight = Decimal(entry)
            except (InvalidOperation, ValueError):
                raise ValueError(f"invalid weight: {entry!r}") from None
        else:
            raise ValueError(f"invalid weight: {entry!r}")
        if not weight.is_finite():
            raise ValueError("weights must be finite")
        if weight < 0:
            raise ValueError("weights must be >= 0")
        weights.append(weight)
    total_weight = sum(weights, Decimal("0"))
    if total_weight <= 0:
        raise ValueError("at least one weight must be > 0")
    negative = amount < 0
    cents = abs(total_cents_exact)  # int, non-negative
    # Convert weights to Fractions for exact rational arithmetic
    weight_fracs = [_decimal_to_fraction(w) for w in weights]
    total_weight_frac = Fraction(0, 1)
    for wf in weight_fracs:
        total_weight_frac += wf
    # total_weight_frac >0 guaranteed
    floors = []
    remainders = []
    for wf in weight_fracs:
        if wf == 0:
            floors.append(0)
            remainders.append(Fraction(0, 1))
        else:
            exact = Fraction(cents) * wf / total_weight_frac
            f = exact.numerator // exact.denominator
            floors.append(f)
            remainders.append(exact - f)
    remaining = cents - sum(floors)
    # Build order of indices with weight>0 sorted by remainder desc, weight desc, index asc
    eligible = [i for i, wf in enumerate(weight_fracs) if wf > 0]
    def cmp(a, b):
        ra = remainders[a]
        rb = remainders[b]
        if ra != rb:
            return -1 if ra > rb else 1
        wa = weight_fracs[a]
        wb = weight_fracs[b]
        if wa != wb:
            return -1 if wa > wb else 1
        if a != b:
            return -1 if a < b else 1
        return 0
    eligible.sort(key=cmp_to_key(cmp))
    for i in eligible[:remaining]:
        floors[i] += 1
    parts = []
    for floor_cents in floors:
        # Build Decimal quantized to 2 dp without context precision limits
        dollars = floor_cents // 100
        cents_rem = floor_cents % 100
        # dollars may be large; use string construction
        s = f"{dollars}.{cents_rem:02d}"
        part = Decimal(s)
        if negative and floor_cents != 0:
            part = -part
        # Ensure exponent -2 (Decimal(s) already has -2 unless we need to handle large? it is -2)
        # Quantize is not needed but ensure exponent -2; if floor_cents==0, s is "0.00" ok
        parts.append(part)
    return parts
